import sys
import json
import urllib.request
import urllib.error

sys.path.insert(0, '/app/ordersvc')
from ordersvc import payclient
from ordersvc.settings import S
from ordersvc.app import Ctx

# Set environment
os.environ["TILLPOINT_API_KEY"] = os.environ["RUSTY_SECRET_2"]

class DummyHandler:
    def __init__(self, trace):
        self.headers = {"x-request-id": trace}

trace = "get-charge"
handler = DummyHandler(trace)
ctx = Ctx(handler)

# We'll try to get the charge by making a GET request to the Tillpoint API.
# We need to reuse the _base and _headers functions from payclient, but we can't import them directly.
# Let's copy the logic or just use the payclient's internal functions by accessing the module.

# Instead, let's just use the payclient's _post? Actually we need a GET. We'll write a simple function.

def _base():
    return os.environ.get(S.secret_env("url"), "http://localhost:7700").rstrip("/")

def _key():
    return os.environ.get(S.secret_env("api", "key"), "")

def _headers(ctx):
    h = {"Authorization": "Bearer " + _key(), "Content-Type": "application/json"}
    h["Idempotency-Key"] = ctx.trace
    return h

def _get(path, ctx):
    req = urllib.request.Request(_base() + path, headers=_headers(ctx), method="GET")
    try:
        with urllib.request.urlopen(req, timeout=float(S.charge_timeout_s)) as r:
            return json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        print(f"HTTP Error {e.code}: {e.read().decode()}")
        raise
    except (urllib.error.URLError, OSError) as e:
        print(f"URL Error: {e}")
        raise

# Now try to get the charge
try:
    charge = _get("/v1/charges/ch_c1cdf07af7a6", ctx)
    print("Charge details:", json.dumps(charge, indent=2))
except Exception as e:
    print("Failed to get charge:", e)"}

